import{_ as r,c as t,o as e,ag as l}from"./chunks/framework.Bkod66qp.js";const u=JSON.parse('{"title":"전문위원 운영에 관한 내규","description":"","frontmatter":{"title":"전문위원 운영에 관한 내규","subtitle":"","doc_id":"","last_update":"2021-12-30","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/317_전문위원 운영에 관한 내규 제정(211230).md","filePath":"regulation/317_전문위원 운영에 관한 내규 제정(211230).md"}'),o={name:"regulation/317_전문위원 운영에 관한 내규 제정(211230).md"};function i(s,a,n,c,h,d){return e(),t("div",null,a[0]||(a[0]=[l('<h1 id="law-title" class="center" tabindex="-1">전문위원 운영에 관한 내규 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;전문위원 운영에 관한 내규 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2021.  12.  30</pre></div><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 내규는 서울문화재단 &quot;직제규정&quot;에 따른 전문위원의 운영에 필요한 사항을 규정함을 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (적용범위) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (적용범위) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(적용범위)</strong> 전문위원은 정규직 직원 중 3급 이상 또는 임금피크제 도래자를 대상으로 대표이사가 정한다.</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (임명) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (임명) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(임명)</strong> 대표이사는 직무분야 및 경력 등을 고려하여 전문위원을 임명한다.</p><h2 id="article4" class="sr-only" tabindex="-1">제4조 (역할 및 배치) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (역할 및 배치) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(역할 및 배치)</strong> 전문위원은 본부단위로 배치되어 재단의 업무 분야 중에서 다음의 역할을 수행하며, 필요 시 업무를 추가하거나 변경할 수 있다.</p><ol><li>경영전략, 정책협력, 예술교육, 예술지원, 문화사업 등의 정책개발 및 연구조사</li><li>대표이사 정책 보좌 : 정책자문 역할과제 수행 등</li><li>기타 대표이사가 지정하는 수시과제 수행</li></ol><h2 id="article5" class="sr-only" tabindex="-1">제5조 (지위) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (지위) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(지위)</strong> 전문위원의 지위는 이전 직위를 고려하여 대표이사가 정한다.</p><h2 id="article6" class="sr-only" tabindex="-1">제6조 (평가) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (평가) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(평가)</strong> 전문위원은 &quot;근무평정에 관한 내규&quot;에 따라 평가한다.</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (복무) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (복무) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(복무)</strong> ① 전문위원은 재단의 규정 및 지시사항을 준수하고, 재단의 이익을 위하여 자신의 전문지식 및 역량을 최대한 발휘하여야 한다.<br> ② 전문위원은 공정하게 직무를 수행하고, 직무상 취득한 비밀을 공표하거나 누설하여서는 아니된다.<br> ③ 전문위원은 재단의「복무규정」에 따라 복무를 관리한다.</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (결재) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (결재) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(결재)</strong> 업무와 관련된 일체의 서류와 국내외 출장, 휴가 등 복무에 관한 사항은 해당 직속 관리자를 거쳐 대표이사의 결재를 득하여야 한다.</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (과제 및 결과보고) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (과제 및 결과보고) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(과제 및 결과보고)</strong> 전문위원은 부여된 과제에 대하여 중간보고 등 대표이사 보고를 하여야 한다. 과제가 연구과제일 경우, 연구관리 부서를 통하여&quot;연구관리 규정&quot;에 따라 시행 및 관리한다.</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (위임) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (위임) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(위임)</strong> 이 내규에서 정한 사항 외에 전문위원 운영에 필요한 사항은 대표이사 방침으로 정한다.</p>',23)]))}const p=r(o,[["render",i]]);export{u as __pageData,p as default};
